(52, '헐 이거 명기 아닌가요 금손이십니다!', 10, b'0', b'0', '2026-06-10 12:49:01', '2026-06-10 12:49:01'),
(52, '부품 구하기 힘드셨을텐데 대단합니다.', 11, b'0', b'0', '2026-06-10 19:17:16', '2026-06-10 19:17:16'),
(53, '깔끔하게 배선 정리 잘 하셨네요!', 7, b'0', b'0', '2026-06-10 05:35:24', '2026-06-10 05:35:24'),
(53, '이제 무거워서 멀티이펙터로 기변하게 되실 겁니다 ㅋㅋ', 4, b'0', b'0', '2026-06-10 11:38:56', '2026-06-10 11:38:56'),
(54, '와 드럼러들의 최고 로망 방음부스 ㅠㅠ 부러워요.', 12, b'0', b'0', '2026-06-11 17:56:44', '2026-06-11 17:56:44'),
(54, '새벽에 쳐도 안 들리나요?? 대박이네요.', 5, b'0', b'0', '2026-06-11 23:32:35', '2026-06-11 23:32:35'),
(55, '골드탑은 진리죠. 픽업 뭐 박혀있나요?', 11, b'0', b'0', '2026-06-10 15:32:16', '2026-06-10 15:32:16'),
